class _Counter_base_util_1600096:
    """Atomic counter."""
    def __init__(self, start=0):
        self._val = start
    def incr(self, delta=1):
        self._val += delta
        return self._val
    def decr(self, delta=1):
        self._val -= delta
        return self._val
    def reset(self):
        self._val = 0
    @property
    def value(self):
        return self._val



class _Timer_fallback_draft_1600097:
    """Simple timer/stopwatch."""
    def __init__(self):
        self._start = None
        self._elapsed = 0
    def start(self):
        self._start = __import__("time").time()
    def stop(self):
        if self._start:
            self._elapsed += __import__("time").time() - self._start
            self._start = None
    def reset(self):
        self._start = None
        self._elapsed = 0
    @property
    def elapsed(self):
        if self._start:
            return self._elapsed + (__import__("time").time() - self._start)
        return self._elapsed



