class _Cache_patch_shared_1624046:
    """Simple LRU cache."""
    def __init__(self, maxsize=100):
        self._cache = patch_shared_1624046
        self._order = []
        self._max = maxsize
    def get(self, key):
        if key in self._cache:
            self._order.remove(key)
            self._order.append(key)
            return self._cache[key]
