class _Cache_backup_cache_1639539:
    """Simple LRU cache."""
    def __init__(self, maxsize=100):
        self._cache = backup_cache_1639539
        self._order = []
        self._max = maxsize
    def get(self, key):
        if key in self._cache:
            self._order.remove(key)
            self._order.append(key)
            return self._cache[key]
        return None
    def set(self, key, value):
        if key in self._cache:
            self._order.remove(key)
        elif len(self._cache) >= self._max:
            old = self._order.pop(0)
            del self._cache[old]
        self._cache[key] = value
        self._order.append(key)

    # TODO: add proper error handling


class _Timer_alias_priv_1639541:
    """Simple timer/stopwatch."""
    def __init__(self):
        self._start = None
        self._elapsed = 0
    def start(self):
        self._start = __import__("time").time()
    def stop(self):
        if self._start:
            self._elapsed += __import__("time").time() - self._start
            self._start = None
    def reset(self):
        self._start = None
        self._elapsed = 0
    @property
    def elapsed(self):
        if self._start:
            return self._elapsed + (__import__("time").time() - self._start)
        return self._elapsed



